loop_push(codegen_scope *s, enum looptype t)
{
  struct loopinfo *p = (struct loopinfo *)codegen_palloc(s, sizeof(struct loopinfo));

  p->type = t;
  p->pc0 = p->pc1 = p->pc2 = p->pc3 = JMPLINK_START;
  p->prev = s->loop;
  p->acc = cursp();
  s->loop = p;

  return p;
}

